atts.custom_css:
selector{align-self:stretch;width:100%;}
selector:hover { border-color:rgb(255 255 255 / var(--tw-border-opacity, 1)) !important; }
:where(selector){line-height:16px;text-align:center;transition:color 0.3s cubic-bezier(0.4, 0, 0.2, 1), background-color 0.3s cubic-bezier(0.4, 0, 0.2, 1), border-color 0.3s cubic-bezier(0.4, 0, 0.2, 1), text-decoration-color 0.3s cubic-bezier(0.4, 0, 0.2, 1), fill 0.3s cubic-bezier(0.4, 0, 0.2, 1), stroke 0.3s cubic-bezier(0.4, 0, 0.2, 1), -webkit-text-decoration-color 0.3s cubic-bezier(0.4, 0, 0.2, 1);}
